from collections import namedtuple
import re

from .base import BaseScfcErrorFixer
from ute_btssm.exception import ScfcFixerError
from ute_btssm.scfc.xml import Range


class _InvalidNumberMessage(
        namedtuple('_InvalidNumberMessage', ['parent_dist_name', 'managed_object_class', 'min_number', 'max_number', 'current_number'])):

    @staticmethod
    def parse_from(validation_message):
        """Parses matching validation messages"""
        parent_dist_name = validation_message.dist_name
        managed_object_class = _InvalidNumberMessage._parse_managed_object_class(validation_message)
        current_number = _InvalidNumberMessage._parse_current_number(validation_message)
        min_number, max_number = _InvalidNumberMessage._parse_range(validation_message)
        return _InvalidNumberMessage(parent_dist_name, managed_object_class, min_number, max_number, current_number)

    @staticmethod
    def _parse_managed_object_class(validation_message):
        match = re.match('The occurrence of managedObject (.*?) ', validation_message.details)
        return match.group(1)

    @staticmethod
    def _parse_range(validation_message):
        match = re.search('number between (.*?) and (.*?),', validation_message.details)
        return int(match.group(1)), int(match.group(2))

    @staticmethod
    def _parse_current_number(validation_message):
        match = re.search(r'but it is (.*?)\.', validation_message.details)
        return int(match.group(1))


class MissingMandatoryManagedObjectFixer(BaseScfcErrorFixer):

    def can_fix(self, validation_message):
        """Returns true if this fixer can fix given SCFC validation error/warning, false otherwise"""
        return validation_message.is_error() and validation_message.details.startswith('The occurrence of managedObject ')

    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""
        parsed_message = _InvalidNumberMessage.parse_from(validation_message)
        if parsed_message.current_number < parsed_message.min_number:
            self._add_missing_managed_objects(parsed_message, param_dictionary, scfc)
        else:
            self._remove_extra_managed_objects(parsed_message, scfc)

    def _add_missing_managed_objects(self, message, param_dictionary, scfc):
        managed_object_in_dict = param_dictionary.get_managed_object(message.managed_object_class)
        id_range = self._get_id_range(managed_object_in_dict)
        existing_ids = self._find_existing_managed_object_ids(scfc, message.managed_object_class, message.parent_dist_name)
        number_of_missing_objects = message.min_number - message.current_number
        for i in range(1, number_of_missing_objects + 1):
            free_id = self._find_free_id(id_range, existing_ids)
            dist_name = message.parent_dist_name + '/' + message.managed_object_class + '-' + str(free_id)
            self._add_managed_object(scfc, managed_object_in_dict, dist_name)
            existing_ids.append(free_id)

    def _get_id_range(self, managed_object_in_dict):
        if managed_object_in_dict.has_id_param() and managed_object_in_dict.get_id_param().has_value_range():
            return managed_object_in_dict.get_id_param().value_range
        else:
            return Range(0, 1000)

    def _remove_extra_managed_objects(self, message, scfc):
        number_of_extra_objects = message.current_number - message.max_number
        existing_ids = self._find_existing_managed_object_ids(scfc, message.managed_object_class, message.parent_dist_name)
        ids_to_remove = sorted(existing_ids)[-number_of_extra_objects:]
        for id in ids_to_remove:
            dist_name = message.parent_dist_name + '/' + message.managed_object_class + '-' + str(id)
            scfc.remove_managed_object(dist_name)

    def _find_existing_managed_object_ids(self, scfc, managed_object_class, parent_dist_name):
        managed_objects = scfc.find_managed_objects(managed_object_class)
        return [managed_object.id for managed_object in managed_objects if managed_object.dist_name.startswith(parent_dist_name)]

    def _find_free_id(self, id_range, existing_ids):
        for i in range(id_range.min_as_int, id_range.max_as_int + 1):
            if i not in existing_ids:
                return i
        raise ScfcFixerError('Cannot find a valid id for managed object (all ids in %s are taken)' % id_range)
